      "state": {
        "thetaSweep": 0
      }
    },
    {
      "title": "A quarter turn out",
      "narration": "Drag θ to π/2. The tracer has rotated a quarter turn counterclockwise and stands about 1.57 units straight above the origin — the plotted dot labeled (π/2, π/2).",
      "state": {
        "thetaSweep": 1.571
      }
    },
    {
      "title": "Half a turn — radius π",
      "narration": "At θ = π the point lies on the negative x-axis, about 3.14 units out. The label (π, π) reads angle first, radius second, and both are the same number.",
      "state": {
        "thetaSweep": 3.142
      }
    },
    {
      "title": "Three quarters and beyond",
      "narration": "Past 5π/4 and 7π/4 the loop keeps widening at a steady rate; the gaps between successive gray circles crossed by the curve stay uniform.",
