var TWO_PI = Math.PI * 2;
var NAVY = '#1F3F6E';
var ACCENT = '#E8792B';
var PAD = 12;

var spState = { theta: 0, interacted: false, playing: false, highlight: null };

function T(s) { return { t: 'x', s: s }; }
function F(n, d) { return { t: 'f', n: n, d: d }; }

var marks = [
  { th: Math.PI / 4, plain: 'π/4, π/4', toks: [T('('), F('π', '4'), T(', '), F('π', '4'), T(')')], lx: 0.80, ly: 1.05, align: 'left' },
  { th: Math.PI / 2, plain: 'π/2, π/2', toks: [T('('), F('π', '2'), T(', '), F('π', '2'), T(')')], lx: 0.30, ly: 2.62, align: 'left' },
  { th: Math.PI, plain: 'π, π', toks: [T('(π, π)')], lx: -4.40, ly: 1.00, align: 'center' },
  { th: 5 * Math.PI / 4, plain: '5π/4, 5π/4', toks: [T('('), F('5π', '4'), T(', '), F('5π', '4'), T(')')], lx: -5.25, ly: -2.95, align: 'center' },
  { th: 7 * Math.PI / 4, plain: '7π/4, 7π/4', toks: [T('('), F('7π', '4'), T(', '), F('7π', '4'), T(')')], lx: 5.45, ly: -4.65, align: 'center' },
  { th: TWO_PI, plain: '2π, 2π', toks: [T('(2π, 2π)')], lx: 5.05, ly: 1.05, align: 'center' }
];
marks.forEach(function (m) { m.px = m.th * Math.cos(m.th); m.py = m.th * Math.sin(m.th); });

var spiralPts = [];
for (var i = 0; i <= 480; i++) { var t = TWO_PI * i / 480; spiralPts.push({ x: t * Math.cos(t), y: t * Math.sin(t) }); }

var dotPts = [{ x: 0, y: 0 }].concat(marks.map(function (m) { return { x: m.px, y: m.py }; }));

var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(canvas);

function unit(chart) {
  var s = chart.scales && chart.scales.x;
  if (!s) return 0;
  return s.getPixelForValue(1) - s.getPixelForValue(0);
}
function fontSize(u) { return Math.max(6.5, Math.min(14, u * 0.36)); }

function arrowHead(ctx, x, y, dx, dy, s) {
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - dx * s - dy * s * 0.45, y - dy * s + dx * s * 0.45);
  ctx.lineTo(x - dx * s + dy * s * 0.45, y - dy * s - dx * s * 0.45);
  ctx.closePath();
  ctx.fill();
}

