function drawTokens(ctx, toks, x, y, fs, align) {
  var widths = [], total = 0, k;
  for (k = 0; k < toks.length; k++) {
    var tk = toks[k], w;
    if (tk.t === 'x') { ctx.font = fs + 'px ' + SERIF; w = ctx.measureText(tk.s).width; }
    else {
      ctx.font = (fs * 0.85) + 'px ' + SERIF;
      w = Math.max(ctx.measureText(tk.n).width, ctx.measureText(tk.d).width) + fs * 0.26;
    }
    widths.push(w); total += w;
  }
  var cx = align === 'left' ? x : (align === 'right' ? x - total : x - total / 2);
  ctx.textBaseline = 'middle'; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  for (k = 0; k < toks.length; k++) {
    var tok = toks[k], ww = widths[k];
    if (tok.t === 'x') {
      ctx.font = fs + 'px ' + SERIF; ctx.textAlign = 'left';
      ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(2, fs * 0.38); ctx.strokeText(tok.s, cx, y);
      ctx.fillStyle = '#000'; ctx.fillText(tok.s, cx, y);
    } else {
      ctx.font = (fs * 0.85) + 'px ' + SERIF; ctx.textAlign = 'center';
      var mx = cx + ww / 2, bw = ww - fs * 0.26;
      ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(2, fs * 0.38);
      ctx.strokeText(tok.n, mx, y - fs * 0.55); ctx.strokeText(tok.d, mx, y + fs * 0.58);
      ctx.beginPath(); ctx.moveTo(mx - bw / 2, y); ctx.lineTo(mx + bw / 2, y); ctx.stroke();
      ctx.fillStyle = '#000';
      ctx.fillText(tok.n, mx, y - fs * 0.55); ctx.fillText(tok.d, mx, y + fs * 0.58);
      ctx.strokeStyle = '#000'; ctx.lineWidth = Math.max(1, fs * 0.075);
      ctx.beginPath(); ctx.moveTo(mx - bw / 2, y); ctx.lineTo(mx + bw / 2, y); ctx.stroke();
    }
    cx += ww;
  }
}

var aspectPlugin = {
  id: 'squareAspect',
  beforeUpdate: function (chart) {
    var w, h;
    if (chart.chartArea && chart.chartArea.width > 4 && chart.chartArea.height > 4) {
      w = chart.chartArea.width; h = chart.chartArea.height;
    } else {
      w = (chart.width || 600) - 2 * PAD; h = (chart.height || 500) - 2 * PAD;
    }
    if (!(w > 0 && h > 0)) return;
    var base = 7.8, xh = base, yh = base;
    if (w > h) xh = base * w / h; else yh = base * h / w;
    chart.options.scales.x.min = -xh; chart.options.scales.x.max = xh;
    chart.options.scales.y.min = -yh; chart.options.scales.y.max = yh;
  }
};

var gridPlugin = {
  id: 'polarGrid',
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx, xs = chart.scales.x, ys = chart.scales.y;
    var u = unit(chart); if (!(u > 0)) return;
    var cx = xs.getPixelForValue(0), cy = ys.getPixelForValue(0);
    var fs = fontSize(u), r, k;
    ctx.save();
    ctx.strokeStyle = '#c6c6c6'; ctx.lineWidth = Math.max(0.5, u * 0.025);
    for (r = 1; r <= 7; r++) { ctx.beginPath(); ctx.arc(cx, cy, r * u, 0, TWO_PI); ctx.stroke(); }
    for (k = 0; k < 2; k++) {
      var a = Math.PI / 4 + k * Math.PI / 2;
      ctx.beginPath();
      ctx.moveTo(cx + 7 * u * Math.cos(a), cy - 7 * u * Math.sin(a));
      ctx.lineTo(cx - 7 * u * Math.cos(a), cy + 7 * u * Math.sin(a));
      ctx.stroke();
    }
    var ext = 7.5 * u;
    ctx.strokeStyle = '#000'; ctx.fillStyle = '#000';
    ctx.lineWidth = Math.max(1, u * 0.04);
    ctx.beginPath();
    ctx.moveTo(cx - ext, cy); ctx.lineTo(cx + ext, cy);
    ctx.moveTo(cx, cy - ext); ctx.lineTo(cx, cy + ext);
    ctx.stroke();
    var asz = Math.max(4, u * 0.28);
    arrowHead(ctx, cx + ext, cy, 1, 0, asz);
    arrowHead(ctx, cx - ext, cy, -1, 0, asz);
    arrowHead(ctx, cx, cy - ext, 0, -1, asz);
    arrowHead(ctx, cx, cy + ext, 0, 1, asz);

    var tk = Math.max(2, u * 0.13);
    ctx.font = fs + 'px sans-serif';
    var stepI = fs < 8 ? 2 : 1;
    for (var i = -7; i <= 7; i++) {
      if (!i) continue;
      var x = cx + i * u, y = cy - i * u;
      ctx.beginPath();
      ctx.moveTo(x, cy - tk); ctx.lineTo(x, cy + tk);
      ctx.moveTo(cx - tk, y); ctx.lineTo(cx + tk, y);
      ctx.stroke();
      if (i % stepI) continue;
      ctx.fillStyle = '#000';
      ctx.textAlign = 'center'; ctx.textBaseline = 'top';
      ctx.fillText(String(i), x, cy + tk + fs * 0.28);
      ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
      ctx.fillText(String(i), cx - tk - fs * 0.32, y);
    }
    ctx.restore();
  }
};

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

var overlayPlugin = {
  id: 'spiralOverlay',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, xs = chart.scales.x, ys = chart.scales.y;
    var u = unit(chart); if (!(u > 0)) return;
    var X = function (v) { return xs.getPixelForValue(v); };
    var Y = function (v) { return ys.getPixelForValue(v); };
    var fs = fontSize(u), cx = X(0), cy = Y(0), i;

    if (spState.highlight != null) {
      var m = marks[spState.highlight];
      ctx.save();
      ctx.strokeStyle = 'rgba(232,121,43,0.9)';
      ctx.lineWidth = Math.max(1, u * 0.045);
      ctx.setLineDash([Math.max(3, u * 0.22), Math.max(2, u * 0.16)]);
      ctx.beginPath(); ctx.arc(cx, cy, m.th * u, 0, TWO_PI); ctx.stroke();
      ctx.setLineDash([]);
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(X(7.3 * Math.cos(m.th)), Y(7.3 * Math.sin(m.th)));
      ctx.stroke();
      ctx.fillStyle = 'rgba(232,121,43,0.95)';
      ctx.beginPath(); ctx.arc(X(m.px), Y(m.py), Math.max(3, u * 0.13), 0, TWO_PI); ctx.fill();
      ctx.restore();
    }

    if (spState.interacted) {
      var th = spState.theta;
      ctx.save();
      if (th > 0.005) {
        ctx.strokeStyle = 'rgba(232,121,43,0.95)';
        ctx.lineWidth = Math.max(1.4, u * 0.06);
        ctx.lineJoin = 'round'; ctx.lineCap = 'round';
        ctx.beginPath();
        var n = Math.max(2, Math.ceil(th / TWO_PI * 400));
        for (i = 0; i <= n; i++) {
          var a = th * i / n;
          var pxx = X(a * Math.cos(a)), pyy = Y(a * Math.sin(a));
          if (i) ctx.lineTo(pxx, pyy); else ctx.moveTo(pxx, pyy);
        }
        ctx.stroke();
        ctx.strokeStyle = ACCENT;
        ctx.lineWidth = Math.max(1.1, u * 0.048);
        ctx.beginPath(); ctx.moveTo(cx, cy);
        ctx.lineTo(X(th * Math.cos(th)), Y(th * Math.sin(th)));
        ctx.stroke();
        ctx.strokeStyle = 'rgba(232,121,43,0.55)';
        ctx.lineWidth = Math.max(1, u * 0.035);
        ctx.beginPath(); ctx.arc(cx, cy, u * 0.85, 0, -th, true); ctx.stroke();
      }
      ctx.fillStyle = ACCENT; ctx.strokeStyle = '#fff';
      ctx.lineWidth = Math.max(1, u * 0.028);
      ctx.beginPath();
      ctx.arc(X(th * Math.cos(th)), Y(th * Math.sin(th)), Math.max(3, u * 0.135), 0, TWO_PI);
      ctx.fill(); ctx.stroke();
      ctx.restore();
    }

    for (i = 0; i < marks.length; i++) {
      drawTokens(ctx, marks[i].toks, X(marks[i].lx), Y(marks[i].ly), fs, marks[i].align);
    }

    if (spState.interacted) {
      var area = chart.chartArea;
      var l1 = 'θ = ' + spState.theta.toFixed(2) + ' rad  (' + (spState.theta / Math.PI).toFixed(2) + 'π)';
      var l2 = 'r = θ = ' + spState.theta.toFixed(2);
      ctx.save();
      ctx.font = fs + 'px sans-serif';
      var pad = fs * 0.55;
      var w = Math.max(ctx.measureText(l1).width, ctx.measureText(l2).width) + pad * 2;
      var h = fs * 2.9 + pad;
      var bx = area.left + 2, by = area.top + 2;
      ctx.fillStyle = 'rgba(255,255,255,0.93)';
      ctx.strokeStyle = ACCENT; ctx.lineWidth = 1;
      roundRect(ctx, bx, by, w, h, 4); ctx.fill(); ctx.stroke();
      ctx.textAlign = 'left'; ctx.textBaseline = 'top';
      ctx.fillStyle = '#7a4212'; ctx.fillText(l1, bx + pad, by + pad * 0.7);
      ctx.fillStyle = '#7a4212'; ctx.fillText(l2, bx + pad, by + pad * 0.7 + fs * 1.35);
      ctx.restore();
    }
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'scatter',
  data: {
    datasets: [
      {
        label: 'r = θ',
        data: spiralPts,
        showLine: true,
        pointRadius: 0,
        borderColor: NAVY,
        borderWidth: function (c) { return Math.max(1.6, unit(c.chart) * 0.075); },
        borderCapStyle: 'round',
        borderJoinStyle: 'round',
        tension: 0,
        order: 2
      },
      {
        label: 'sample points',
        data: dotPts,
        showLine: false,
        pointRadius: function (c) { return Math.max(2, unit(c.chart) * 0.105); },
        backgroundColor: '#000',
        borderWidth: 0,
        order: 1
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    layout: { padding: PAD },
    scales: {
      x: { type: 'linear', display: false, min: -7.8, max: 7.8, grid: { display: false } },
      y: { type: 'linear', display: false, min: -7.8, max: 7.8, grid: { display: false } }
    },
    plugins: { legend: { display: false }, tooltip: { enabled: false } }
  },
  plugins: [aspectPlugin, gridPlugin, overlayPlugin]
});
window.__markRendered();

/* ── interaction: hover + click on the labelled dots ─────────────────────── */
function hitMark(clientX, clientY) {
  var rect = canvas.getBoundingClientRect();
  var px = clientX - rect.left, py = clientY - rect.top;
  var u = unit(chart); if (!(u > 0)) return -1;
  var xs = chart.scales.x, ys = chart.scales.y;
  var tol = Math.max(9, u * 0.35), best = -1, bd = 1e9;
  for (var i = 0; i < marks.length; i++) {
    var dx = xs.getPixelForValue(marks[i].px) - px;
    var dy = ys.getPixelForValue(marks[i].py) - py;
    var d = Math.sqrt(dx * dx + dy * dy);
    if (d < tol && d < bd) { bd = d; best = i; }
  }
  return best;
}

canvas.addEventListener('mousemove', function (e) {
  var i = hitMark(e.clientX, e.clientY);
  if (i >= 0) {
    var m = marks[i];
    canvas.style.cursor = 'pointer';
    showTooltip('(' + m.plain + ')  →  angle θ = ' + m.th.toFixed(2) + ' rad, radius r = ' + m.th.toFixed(2) + ' units', e);
  } else {
    canvas.style.cursor = 'default';
    hideTooltip();
  }
});
canvas.addEventListener('mouseleave', function () { hideTooltip(); canvas.style.cursor = 'default'; });

canvas.addEventListener('click', function (e) {
  var i = hitMark(e.clientX, e.clientY);
  if (i < 0) { spState.highlight = null; chart.update('none'); return; }
  var m = marks[i];
  stopAnim();
  spState.highlight = i;
  spState.interacted = true;
  spState.theta = m.th;
  syncSlider();
  chart.update('none');
  showPopup('Point (' + m.plain + ')',
    'Sweeping through an angle of ' + m.th.toFixed(2) + ' radians puts the point exactly ' + m.th.toFixed(2) +
    ' units from the pole, because the rule is r = θ. The solid orange ray marks the angle and the dashed orange circle marks the matching radius. ' +
    'They meet on the spiral, which is why both entries of the ordered pair are the same number.');
});

/* ── controls ────────────────────────────────────────────────────────────── */
function syncSlider() {
  var inp = document.getElementById('thetaSweepInput');
  var out = document.getElementById('thetaSweepVal');
  if (inp) inp.value = spState.theta;
  if (out) out.value = spState.theta.toFixed(2);
}

function update_thetaSweep(v) {
  stopAnim();
  spState.interacted = true;
  spState.theta = Math.max(0, Math.min(TWO_PI, v));
  chart.update('none');
}

var animRaf = null, animLast = 0;
function startAnim() {
  spState.playing = true;
  spState.interacted = true;
  var b = document.getElementById('playBtn');
  if (b) { b.textContent = '⏸ Pause sweep'; b.classList.add('active'); }
  animLast = performance.now();
  animRaf = requestAnimationFrame(animTick);
}
function animTick(ts) {
  if (!spState.playing) return;
  var dt = (ts - animLast) / 1000; animLast = ts;
  spState.theta += dt * (TWO_PI / 6.5);
  if (spState.theta > TWO_PI) spState.theta = 0;
  syncSlider();
  chart.update('none');
  animRaf = requestAnimationFrame(animTick);
}
function stopAnim() {
  spState.playing = false;
  if (animRaf) cancelAnimationFrame(animRaf);
  animRaf = null;
  var b = document.getElementById('playBtn');
  if (b) { b.textContent = '▶ Sweep the radius'; b.classList.remove('active'); }
}
function trigger_traceSpiral() { if (spState.playing) stopAnim(); else startAnim(); }

function trigger_reset() {
  stopAnim();
  spState.theta = 0;
  spState.highlight = null;
  spState.interacted = false;
  syncSlider();
  chart.update('none');
  hidePopup();
}

/* ── demo step player ────────────────────────────────────────────────────── */
var steps = [
  { title: 'Start at the pole', narration: 'At θ = 0 the radius is also 0, so the curve begins exactly at the origin. The tracer sits on the pole with no radius segment yet.', theta: 0 },
  { title: 'A quarter turn out', narration: 'Drag θ to π/2. The tracer has rotated a quarter turn counterclockwise and stands about 1.57 units straight above the origin — the plotted dot labeled (π/2, π/2).', theta: 1.571 },
  { title: 'Half a turn — radius π', narration: 'At θ = π the point lies on the negative x-axis, about 3.14 units out. The label (π, π) reads angle first, radius second, and both are the same number.', theta: 3.142 },
  { title: 'Three quarters and beyond', narration: 'Past 5π/4 and 7π/4 the loop keeps widening at a steady rate; the gaps between successive gray circles crossed by the curve stay uniform.', theta: 5.498 },
  { title: 'One full turn closes the loop', narration: 'At θ = 2π the curve returns to the positive x-axis but now about 6.28 units out instead of at the origin — one full revolution has pushed the radius out by 2π.', theta: 6.283 },
  { title: 'Watch it drawn', narration: 'Play the animation and click any labeled dot: the rotating ray lengthens as it turns, and each highlighted ray plus its matching circle confirms r = θ at that point.', theta: 6.283 }
];
var stepIdx = 0;

function showStepText() {
  var s = steps[stepIdx];
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length;
}
function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  showStepText();
  if (stepIdx === 5) {
    spState.interacted = true;
    if (!spState.playing) startAnim();
  } else {
    stopAnim();
    spState.interacted = true;
    spState.theta = s.theta;
    if (stepIdx === 0) spState.highlight = null;
    syncSlider();
    chart.update('none');
  }
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

showStepText();

document.addEventListener('fig-resize', function () { if (chart) chart.resize(); });
